      generation: TimekeepingOwnership.current.generation, disposition: "active", entries: [701]
    )
  end

  def refusal_record_adapter(state, conflicts: [])
    outcome = ->(name) { Invoices::ReservationOutcome.new(state: name, conflicts: name == state ? conflicts : [], counts: {}) }
    RecordingReservationAdapter.new(prepare: outcome.call(state), commit: outcome.call("committed"), abort: outcome.call("aborted"))
