RSpec.describe Invoices::OperationCoordinator, "prepare refusal record on retry", committed_data: true do
  def retry_refusal_request(invoice)
    Invoices::ReservationRequest.new(
      company_id: invoice.company_id, invoice_id: invoice.id, operation_id: SecureRandom.uuid,
      generation: TimekeepingOwnership.current.generation, disposition: "active", entries: [703]
    )
  end

  def retry_refusal_adapter(state)
    conflicts = state == "refused" ? [{ entry_id: 703, reason: "on_another_invoice" }] : []
    RecordingReservationAdapter.new(
      prepare: Invoices::ReservationOutcome.new(state:, conflicts:, counts: {}),
      commit: Invoices::ReservationOutcome.new(state: "committed", conflicts: [], counts: {}),
      abort: Invoices::ReservationOutcome.new(state: "aborted", conflicts: [], counts: {})
    )
  end

  def retry_refusal_save(invoice, state)
    request = retry_refusal_request(invoice)
    ApplicationRecord.transaction do
      described_class.new(reservations: retry_refusal_adapter(state))
        .call(request, holding: { entry_ids: [703], disposition: "active" })
    end
  rescue Invoices::OperationErrors::Refused
    nil
  end

  # "Add units that gather the required real signals and prove the command reports them."
  # Each refused prepare is one refusal; a retry that the service prepares is not one.
  it "adds a prepare refusal row for a retry only when the retry is refused again" do
    invoice = create(:invoice)
    rows = TimekeepingPrepareRefusal.where(company_id: invoice.company_id)

    retry_refusal_save(invoice, "refused")
    expect(rows.count).to eq(1)

    retry_refusal_save(invoice, "refused")
    expect(rows.count).to eq(2)

    retry_refusal_save(invoice, "prepared")
    expect(rows.count).to eq(2)
  end
end

RSpec.describe Invoices::OperationCoordinator, "prepare refusal record write failure", committed_data: true do
  # "Add units that gather the required real signals and prove the command reports them."
  # Recording the refusal for alerts must never change what the invoice save answers or the
  # intent settlement that runs beside it.
  it "keeps the Refused error and the failed intent when the prepare refusal record cannot be written" do
    invoice = create(:invoice)
    request = Invoices::ReservationRequest.new(
      company_id: invoice.company_id, invoice_id: invoice.id, operation_id: SecureRandom.uuid,
      generation: TimekeepingOwnership.current.generation, disposition: "active", entries: [704]
    )
    refused = Invoices::ReservationOutcome.new(state: "refused", conflicts: [{ entry_id: 704, reason: "on_another_invoice" }], counts: {})
    adapter = RecordingReservationAdapter.new(
      prepare: refused,
      commit: Invoices::ReservationOutcome.new(state: "committed", conflicts: [], counts: {}),
      abort: Invoices::ReservationOutcome.new(state: "aborted", conflicts: [], counts: {})
    )
    allow(TimekeepingPrepareRefusal).to receive(:insert_all!).and_raise(ActiveRecord::StatementInvalid, "refusal table down")
    allow(Rails.error).to receive(:report).and_call_original

    expect do
      ApplicationRecord.transaction do
        described_class.new(reservations: adapter).call(request, holding: { entry_ids: [704], disposition: "active" })
      end
    end.to raise_error(Invoices::OperationErrors::Refused) { |error| expect(error.outcome).to eq(refused) }

